  "py": "import asyncio\nfrom dataclasses import dataclass\nfrom datetime import timedelta\n\nfrom temporalio import activity, workflow\nfrom temporalio.exceptions import ApplicationError\n\nTASK_QUEUE = \"events\"\nACTIVITY_OPTS = dict(start_to_close_timeout=timedelta(seconds=30))\nMAX_SEATS_PER_BOOKING = 4\n\n\n@dataclass\nclass Reservation:\n    user: str\n    seats: list[str]\n\n\n@dataclass\nclass Booking:\n    booking_id: str\n    seats: list[str]\n    hold_id: str\n\n\n@activity.defn\nasync def place_payment_hold(user: str, seats: list[str]) -> str:\n    # In production: pre-authorise the card, passing an idempotency key to the provider.\n    if user == \"declined\":\n        raise ApplicationError(\"payment hold declined\", type=\"HoldDeclined\", non_retryable=True)\n    await asyncio.sleep(0.2)  # the slow external call that makes races possible\n    return f\"hold-{user}-{'-'.join(seats)}\"\n\n\n@workflow.defn\nclass EventWorkflow:\n    @workflow.init\n    def __init__(self, seats: list[str]) -> None:\n        self.owner: dict[str, str] = {s: \"\" for s in seats}  # \"\" means free (dict: deterministic order)\n        self.lock = asyncio.Lock()\n        self.sales_closed = False\n\n    @workflow.update\n    async def reserve(self, r: Reservation) -> Booking:\n        async with self.lock:  # one reservation at a time\n            # AUTHORITATIVE check. The validator below ran earlier and can be stale by now.\n            taken = [s for s in r.seats if self.owner[s] != \"\"]\n            if taken:\n                raise ApplicationError(\n                    f\"seats already taken: {', '.join(taken)}\", type=\"SeatTaken\", non_retryable=True\n                )\n            hold_id = await workflow.execute_activity(\n                place_payment_hold, args=[r.user, r.seats], **ACTIVITY_OPTS\n            )\n            for s in r.seats:  # only mark seats once the money side succeeded\n                self.owner[s] = r.user\n            return Booking(booking_id=f\"bk-{hold_id}\", seats=r.seats, hold_id=hold_id)\n\n    @reserve.validator\n    def validate_reserve(self, r: Reservation) -> None:\n        # Cheap, fast rejection. Never the only line of defence.\n        if self.sales_closed:\n            raise ValueError(\"sales are closed\")\n        if not r.seats or len(r.seats) > MAX_SEATS_PER_BOOKING:\n            raise ValueError(f\"choose 1 to {MAX_SEATS_PER_BOOKING} seats\")\n        unknown = [s for s in r.seats if s not in self.owner]\n        if unknown:\n            raise ValueError(f\"unknown seats: {', '.join(unknown)}\")\n\n    @workflow.signal\n    def close_sales(self) -> None:\n        self.sales_closed = True\n\n    @workflow.run\n    async def run(self, seats: list[str]) -> dict[str, str]:\n        await workflow.wait_condition(lambda: self.sales_closed)\n        await workflow.wait_condition(workflow.all_handlers_finished)  # let in-flight reservations finish\n        return {s: u for s, u in self.owner.items() if u}",
  "ts": "// ===== seats.ts =====\nimport { Mutex } from 'async-mutex';\nimport {\n  allHandlersFinished, ApplicationFailure, condition, defineSignal, defineUpdate, proxyActivities, setHandler,\n} from '@temporalio/workflow';\nimport type * as activities from './seats.activities';\n\nexport const TASK_QUEUE = 'events';\nconst MAX_SEATS_PER_BOOKING = 4;\n\nconst { placePaymentHold } = proxyActivities<typeof activities>({ startToCloseTimeout: '30 seconds' });\n\nexport interface Reservation {\n  user: string;\n  seats: string[];\n}\nexport interface Booking {\n  bookingId: string;\n  seats: string[];\n  holdId: string;\n}\n\nexport const reserveUpdate = defineUpdate<Booking, [Reservation]>('reserve');\nexport const closeSalesSignal = defineSignal('closeSales');\n\nexport async function eventWorkflow(seats: string[]): Promise<Record<string, string>> {\n  const owner: Record<string, string> = Object.fromEntries(seats.map((s) => [s, ''])); // '' means free\n  const lock = new Mutex();\n  let salesClosed = false;\n\n  setHandler(closeSalesSignal, () => { salesClosed = true; });\n\n  setHandler(\n    reserveUpdate,\n    (r) =>\n      lock.runExclusive(async () => {\n        // AUTHORITATIVE check. The validator below ran earlier and can be stale by now.\n        const taken = r.seats.filter((s) => owner[s] !== '');\n        if (taken.length > 0) {\n          throw ApplicationFailure.nonRetryable('seats already taken: ' + taken.join(', '), 'SeatTaken');\n        }\n        const holdId = await placePaymentHold(r.user, r.seats);\n        for (const s of r.seats) owner[s] = r.user; // only mark seats once the money side succeeded\n        return { bookingId: 'bk-' + holdId, seats: r.seats, holdId };\n      }),\n    {\n      // Cheap, fast rejection. Never the only line of defence.\n      validator: (r: Reservation) => {\n        if (salesClosed) throw new Error('sales are closed');\n        if (r.seats.length === 0 || r.seats.length > MAX_SEATS_PER_BOOKING) {\n          throw new Error('choose 1 to ' + MAX_SEATS_PER_BOOKING + ' seats');\n        }\n        const unknown = r.seats.filter((s) => !(s in owner));\n        if (unknown.length > 0) throw new Error('unknown seats: ' + unknown.join(', '));\n      },\n    },\n  );\n\n  await condition(() => salesClosed);\n  await condition(allHandlersFinished); // let in-flight reservations finish\n  return Object.fromEntries(Object.entries(owner).filter(([, u]) => u !== ''));\n}\n\n// ===== seats.activities.ts =====\nimport { ApplicationFailure } from '@temporalio/activity';\n\nexport const holdLog: string[] = []; // test hook: how many real charges happened\n\nexport async function placePaymentHold(user: string, seats: string[]): Promise<string> {\n  // In production: pre-authorise the card, passing an idempotency key to the provider.\n  holdLog.push(user + ':' + seats.join(','));\n  if (user === 'declined') throw ApplicationFailure.nonRetryable('payment hold declined', 'HoldDeclined');\n  await new Promise((r) => setTimeout(r, 200)); // the slow external call that makes races possible\n  return 'hold-' + user + '-' + seats.join('-');\n}"
