  "py": "import asyncio\nfrom dataclasses import dataclass\nfrom datetime import timedelta\n\nfrom temporalio import activity, workflow\nfrom temporalio.client import Client\nfrom temporalio.client import WithStartWorkflowOperation\nfrom temporalio.common import WorkflowIDConflictPolicy\nfrom temporalio.exceptions import ApplicationError\n\nTASK_QUEUE = \"payments\"\nACTIVITY_OPTS = dict(start_to_close_timeout=timedelta(seconds=30))\nSETTLEMENT_DELAY = timedelta(seconds=1)  # in production: hours or days\n\n\n@dataclass\nclass AuthRequest:\n    card_token: str\n    amount: int\n\n\n@dataclass\nclass AuthResult:\n    approved: bool\n    auth_id: str = \"\"\n    reason: str = \"\"\n\n\n@activity.defn\nasync def authorize_card(req: AuthRequest) -> AuthResult:\n    # In production: call the payment provider.\n    if req.card_token == \"tok_declined\":\n        return AuthResult(approved=False, reason=\"insufficient funds\")\n    return AuthResult(approved=True, auth_id=\"auth-\" + req.card_token)\n\n\n@activity.defn\nasync def capture_payment(auth_id: str) -> None:\n    activity.logger.info(\"captured %s\", auth_id)\n\n\n@activity.defn\nasync def send_receipt(order_id: str) -> None:\n    activity.logger.info(\"receipt for %s\", order_id)\n\n\n@workflow.defn\nclass PaymentWorkflow:\n    def __init__(self) -> None:\n        self.auth: AuthResult | None = None\n        self.lock = asyncio.Lock()\n\n    @workflow.update\n    async def authorize(self, req: AuthRequest) -> AuthResult:\n        async with self.lock:\n            if self.auth is not None:  # already decided: repeat calls get the same answer\n                return self.auth\n            result = await workflow.execute_activity(authorize_card, req, **ACTIVITY_OPTS)\n            self.auth = result\n        if not result.approved:\n            # Raising ApplicationError FAILS THE UPDATE (the caller sees it); the workflow lives on.\n            raise ApplicationError(result.reason, type=\"CardDeclined\", non_retryable=True)\n        return result\n\n    @workflow.run\n    async def run(self, order_id: str) -> str:\n        await workflow.wait_condition(lambda: self.auth is not None)\n        await workflow.wait_condition(workflow.all_handlers_finished)\n        if not self.auth.approved:\n            return \"declined\"\n        # The caller already has its answer; the slow part continues in the background.\n        await workflow.execute_activity(capture_payment, self.auth.auth_id, **ACTIVITY_OPTS)\n        await workflow.sleep(SETTLEMENT_DELAY)\n        await workflow.execute_activity(send_receipt, order_id, **ACTIVITY_OPTS)\n        return \"settled\"\n\n\n# ---- client side: start the workflow AND get the authorisation answer in one call ----\nasync def authorize_and_start(client: Client, order_id: str, req: AuthRequest, request_id: str | None = None):\n    start_op = WithStartWorkflowOperation(\n        PaymentWorkflow.run,\n        order_id,\n        id=f\"payment-{order_id}\",\n        task_queue=TASK_QUEUE,\n        id_conflict_policy=WorkflowIDConflictPolicy.FAIL,  # a second payment for this order is an error\n    )\n    result = await client.execute_update_with_start_workflow(\n        PaymentWorkflow.authorize, req, start_workflow_operation=start_op,\n        id=request_id or f\"auth-{order_id}\",  # the Update ID doubles as an idempotency key\n    )\n    return result, await start_op.workflow_handle()",
  "ts": "// ===== payment.ts =====\nimport { Mutex } from 'async-mutex';\nimport {\n  allHandlersFinished, ApplicationFailure, condition, defineUpdate, proxyActivities, setHandler, sleep,\n} from '@temporalio/workflow';\nimport type * as activities from './payment.activities';\nimport type { AuthRequest, AuthResult } from './payment.activities';\n\nexport const TASK_QUEUE = 'payments';\nconst SETTLEMENT_DELAY = '1 second'; // in production: hours or days\n\nconst { authorizeCard, capturePayment, sendReceipt } = proxyActivities<typeof activities>({\n  startToCloseTimeout: '30 seconds',\n});\n\nexport const authorizeUpdate = defineUpdate<AuthResult, [AuthRequest]>('authorize');\n\nexport async function paymentWorkflow(orderId: string): Promise<string> {\n  let auth: AuthResult | undefined;\n  const lock = new Mutex();\n\n  // With Update-With-Start the update is delivered before this function's first await,\n  // so the handler MUST be registered up here.\n  setHandler(authorizeUpdate, async (req) => {\n    const result = await lock.runExclusive(async () => {\n      if (auth !== undefined) return auth; // already decided: repeat calls get the same answer\n      auth = await authorizeCard(req);\n      return auth;\n    });\n    if (!result.approved) {\n      // Throwing ApplicationFailure FAILS THE UPDATE (the caller sees it); the workflow lives on.\n      throw ApplicationFailure.nonRetryable(result.reason, 'CardDeclined');\n    }\n    return result;\n  });\n\n  await condition(() => auth !== undefined);\n  await condition(allHandlersFinished);\n  const decided = auth as AuthResult | undefined; // set by the update handler\n  if (!decided?.approved) return 'declined';\n\n  // The caller already has its answer; the slow part continues in the background.\n  await capturePayment(decided.authId);\n  await sleep(SETTLEMENT_DELAY);\n  await sendReceipt(orderId);\n  return 'settled';\n}\n\n// ===== payment.activities.ts =====\nexport interface AuthRequest {\n  cardToken: string;\n  amount: number;\n}\nexport interface AuthResult {\n  approved: boolean;\n  authId: string;\n  reason: string;\n}\n\nexport async function authorizeCard(req: AuthRequest): Promise<AuthResult> {\n  // In production: call the payment provider.\n  if (req.cardToken === 'tok_declined') return { approved: false, authId: '', reason: 'insufficient funds' };\n  return { approved: true, authId: 'auth-' + req.cardToken, reason: '' };\n}\n\nexport async function capturePayment(authId: string): Promise<void> {\n  console.log('captured', authId);\n}\n\nexport async function sendReceipt(orderId: string): Promise<void> {\n  console.log('receipt for', orderId);\n}\n\n// ===== payment.client.ts =====\nimport { Client, WithStartWorkflowOperation } from '@temporalio/client';\nimport type { AuthRequest } from './payment.activities';\nimport { authorizeUpdate, paymentWorkflow, TASK_QUEUE } from './payment';\n\n// Start the workflow AND get the authorisation answer back in one call.\nexport async function authorizeAndStart(client: Client, orderId: string, req: AuthRequest, requestId?: string) {\n  const startOp = new WithStartWorkflowOperation(paymentWorkflow, {\n    workflowId: 'payment-' + orderId,\n    taskQueue: TASK_QUEUE,\n    args: [orderId],\n    workflowIdConflictPolicy: 'FAIL', // a second payment for this order is an error\n  });\n  const result = await client.workflow.executeUpdateWithStart(authorizeUpdate, {\n    updateId: requestId ?? 'auth-' + orderId, // the Update ID doubles as an idempotency key\n    args: [req],\n    startWorkflowOperation: startOp,\n  });\n  return { result, handle: await startOp.workflowHandle() };\n}"
